/** Default auto-cruise concurrency when the user has not configured one. */
export const DEFAULT_CRUISE_LIMIT = 5

/** The concurrency budget's real ceiling — the shared board-doc bound (writes
 *  clamp and reads normalize to one pair). Re-exported so board surfaces
 *  keep importing it from the controller. */
export const MAX_CRUISE_LIMIT = CRUISE_LIMIT_MAX

/** Re-export: the waiting-kind union lives beside the question face that
 *  reads it (the official session-status snapshot's `pendingInteraction.kind`);
 *  board surfaces keep importing it from the controller. */
export type { PendingInteractionKind }

/** The sessions face the controller needs (catalog reads + navigation). */
export interface SessionsControllerFace {
  list: {
    getSnapshot(): {
      /** Session ids in native list order (the workspace's own section order). */
      ids?: readonly string[]
      /**
       * List baseline readiness (the native face serves it; absent = an old
       * wiring or a fake — treated as ready, i.e. today's behavior). The
       * FIRST reconcile pass gates on it (see start): a pass against a
       * still-loading list sees no running sessions while the user watches
       * them run — the "刷新后进行中不点亮" race. Every later pass stays
       * subscription-driven.
       */
      phase?: 'pending' | 'ready'
      /** Host session list rows; used to judge whether an execution session finished. */
      byId: Record<string, {
        /**
         * THE SESSION'S OWN turn flag — the only meaning this field ever has.
         * It is deliberately NOT rolled up: the round watchdogs, the settle
         * paths and the external-turn detector all ask "did the turn I sent
         * finish?", and a rolled-up value answers a different question (see
         * session-activity.ts). Surfaces ask the rolled-up question through
         * {@link BoardController.sessionActiveOf}.
         */
        running: boolean
        /**
         * The session this one was spawned from, when the host recorded one.
         * Declared here because the lineage rollup reads it: the official
         * projection writes it from `parentSessionId` (the board's structural
         * row type simply never declared it before). A fork carries a parentId
         * too, which is why lineage gates on `origin` first.
         */
        parentId?: string
        /** Coarse durable origin; `'subagent'` marks an agent-summoned session. */
        origin?: 'subagent'
        /** The session's real workspace root, when the host recorded one. */
        cwd?: string
        /** The workspace id the host attributes the session to, when known. */
        workspaceId?: string
        /** Host "never started" flag (a blank session is a slot, not a conversation). */
        blank?: boolean
        /** Host-computed values for this Session; `agentPreset` is its real composition. */
        projectionValues?: {
          agentPreset?: string | null
          [key: string]: unknown
        }
        /** The session's display title, when the host recorded one (execution-row identity). */
        title?: string
      }>
    }
    subscribe(fn: () => void): () => void
  }
  /** Whether a session still exists in the host session list. */
  exists(id: string): boolean
  /**
   * Show a session's Conversation (the official one-action navigation).
   *
   * OPTIONAL, because the capability itself can be absent: navigation is a
   * separate service from the session catalog, and only the client composition
   * knows whether it was wired. A face that requires it would force every fake
   * and every degraded host to pretend; an absent capability is a real state
   * that returns false below.
   * @returns whether the navigation was actually performed.
   */
  open?(id: string): boolean
}

/**
 * The workspaces face the controller needs: the registry's workspace rows
 * (id + title) for source labels, the run-config picker and drag
 * classification. A bound workspace still never surfaces sessions LIVE (see
 * linked-sessions.ts) — but the folder-drop snapshot DOES read membership,
 * once, at creation, from each row's `sessionIds`: the registry's OWN
 * ownership account (display order), never cwd/title guessing; absent = an
 * old host, fall back to the cwd scan. The registry-global ARCHIVE set is
 * read (archived conversations leave the card's session rows — see
 * taskSessionsOf).
 */
export interface WorkspacesControllerFace {
  list: {
    getSnapshot(): {
      items: readonly { id: string; title: string; sessionIds?: readonly string[] }[]
      archivedSessionIds: readonly string[]
    }
    subscribe(fn: () => void): () => void
  }
}

